mapper.select:
SELECT ranked.* FROM ( SELECT p.*, MATCH(p.title) AGAINST(#{params.keyword} IN NATURAL LANGUAGE MODE) AS title_score, MATCH(p.alias) AGAINST(#{params.keyword} IN NATURAL LANGUAGE MODE) AS alias_score, MATCH(p.metadata_search_text) AGAINST(#{params.keyword} IN NATURAL LANGUAGE MODE) AS metadata_score, CASE WHEN p.title LIKE #{params.likePattern} ESCAPE '!' THEN 1 ELSE 0 END AS title_hit, CASE WHEN p.alias LIKE #{params.likePattern} ESCAPE '!' THEN 1 ELSE 0 END AS alias_hit, JSON_MERGE_PRESERVE('[]',
COALESCE(JSON_SEARCH((CASE WHEN JSON_TYPE(p.metadata) IN ('OBJECT', 'ARRAY') THEN NULLIF(p.metadata_search_text, '') ELSE p.metadata END) COLLATE utf8mb4_unicode_520_ci, 'all', #{pattern}, '!'), '[]')
) AS matched_metadata_paths FROM project p WHERE p.org_id = #{params.orgId} AND p.resource_status = 1 AND p.deleted_at IS NULL
AND p.type_id = #{params.typeId}
) ranked WHERE title_score > 0 OR alias_score > 0 OR title_hit = 1 OR alias_hit = 1 OR JSON_LENGTH(matched_metadata_paths) > 0 ORDER BY ( 5 * (title_score + CASE WHEN title_score > 0 OR title_hit = 1 THEN 1 ELSE 0 END) + 3 * (alias_score + CASE WHEN alias_score > 0 OR alias_hit = 1 THEN 1 ELSE 0 END) + CASE WHEN JSON_LENGTH(matched_metadata_paths) > 0 THEN metadata_score + 1 ELSE 0 END + CASE WHEN title = #{params.keyword} THEN 20 ELSE 0 END + CASE WHEN alias = #{params.keyword} THEN 10 ELSE 0 END ) DESC,
updated_at created_at
ASC, id ASC DESC, id DESC
